async function D_APPLY(str, fcn, foo = false) {
  let res = 0;
  if (!fcn) {
    return false;
  } else {
    res = foo ? (await apply(fcn, foo)) : (await apply(fcn));
    return res;
  }
}

async function QUEUE(interrupt_routine, tick_number) {
  let clocker_int = 0;
  put(clocker_int = await INT(interrupt_routine), C_TICK, tick_number);
  return clocker_int;
}

async function INT(rtn, e = 0, c_ = 0, int = false) {
  e = g.C_TABLE + C_TABLELEN;
  c_ = g.C_TABLE + g.C_INTS;
  for (;;) {
    if (c_ == e) {
      if (!int) {
        if (g.C_INTS < C_INTLEN) {
          tell("Bug #25I\n");
        }
        g.C_INTS = g.C_INTS - C_INTLEN;
        int = g.C_TABLE + g.C_INTS;
      }
      put(int, C_RTN, rtn);
      return int;
    } else if (eq(get(c_, C_RTN), rtn)) {
      return c_;
    } else if (!int && (get(c_, C_RTN) == 0)) {
      int = c_;
    }
    c_ = c_ + C_INTLEN;
  }
}

async function CLOCKER() {
  let c_ = 0, e = 0, tick = 0, rtn = 0, flg = false;
  if (g.CLOCK_WAIT) {
    g.CLOCK_WAIT = false;
    return false;
  }
  c_ = g.C_TABLE + g.C_INTS;
  e = g.C_TABLE + C_TABLELEN;
  for (;;) {
    if (c_ == e) {
      return flg;
    }
    rtn = get(c_, C_RTN);
    if (!(rtn == 0)) {
      tick = get(c_, C_TICK);
      if (tick == (-1)) {
        if (await apply(rtn)) {
          flg = true;
        }
      } else {
        tick = tick - g.ELAPSED_TIME;
        if (tick > 0) {
          put(c_, C_TICK, tick);
        } else {
          put(c_, C_RTN, 0);
          if (await apply(rtn)) {
            flg = true;
          }
        }
      }
    }
    c_ = c_ + C_INTLEN;
  }
}

