async function ITALICIZE(str, no_caps$ = false) {
  let len = 0, ptr = 2, char = 0, scripting_on = false;
  bufOut(false);
  bufOut(true);
  if (btst(get(0, 8), 1)) {
    scripting_on = true;
  }
  if (scripting_on) {
    dirOut(D_PRINTER_OFF);
  }
  dirOut(D_SCREEN_OFF);
  dirOut(D_TABLE_ON, g.SL_BUFFER);
  tell(S(str));
  dirOut(D_TABLE_OFF);
  if (scripting_on) {
    dirOut(D_PRINTER_ON);
  }
  if (!(isVerb(V.SCRIPT, V.UNSCRIPT))) {
    dirOut(D_SCREEN_ON);
  }
  len = get(g.SL_BUFFER, 0) + 1;
  if (len == 1) {
    return true;
  } else if ((getb(0, 18) == 0) || (getb(0, 1) & 8)) {
    highlight(H_ITALIC);
    loop1: for (;;) {
      char = getb(g.SL_BUFFER, ptr);
      if (char == 32) {
        highlight(H_NORMAL);
        printC(32);
        highlight(H_ITALIC);
      } else {
        printC(char);
      }
      if (ptr == len) {
        break loop1;
      } else {
        ptr = ptr + 1;
      }
    }
    return highlight(H_NORMAL);
  } else if (no_caps$) {
    tell(S(str));
    return true;
  } else {
    for (;;) {
      char = getb(g.SL_BUFFER, ptr);
      if ((char > 96) && (char < 123)) {
        char = char - 32;
      }
      printC(char);
      if (ptr == len) {
        return true;
      } else {
        ptr = ptr + 1;
      }
    }
  }
}

