async function CHANGE_LEXV(ptr, wrd, bptr = false) {
  let x = 0, y = 0, z = 0;
  if (bptr) {
    x = 2 + (2 * (ptr - P_LEXELEN));
    y = getb(g.P_LEXV, x);
    z = 2 + (2 * ptr);
    putb(g.P_LEXV, z, y);
    putb(g.AGAIN_LEXV, z, y);
    y = getb(g.P_LEXV, 1 + x);
    z = 3 + (2 * ptr);
    putb(g.P_LEXV, z, y);
    putb(g.AGAIN_LEXV, z, y);
  }
  put(g.P_LEXV, ptr, wrd);
  return put(g.AGAIN_LEXV, ptr, wrd);
}

