async function ITAKE_CHECK(tbl, ibits) {
  let ptr = 0, obj = 0, taken = 0;
  if ((ptr = get(tbl, P_MATCHLEN)) && (btst(ibits, SHAVE) || btst(ibits, STAKE))) {
    for (;;) {
      if ((ptr = ptr - 1) < 0) {
        return true;
      } else {
        obj = get(tbl, ptr + 1);
        if (obj == IT) {
          if (!(await ACCESSIBLE$(g.P_IT_OBJECT))) {
            tell(S(g.REFERRING), "\n");
            return false;
          } else {
            obj = g.P_IT_OBJECT;
          }
        }
        if ((await HELD$(obj)) || (obj == HANDS || obj == HEAD || obj == CLOTHES) || (isVerb(V.SGIVE) && (g.WINNER == SPEAR_CARRIER)) || ((obj == GUN) && (g.WINNER == SABOTEURS || g.WINNER == NATIONAL_GUARDSMAN)) || ((obj == SHOWER || obj == BATHROOM_OBJECT || obj == RECORD_BUFFER) && isVerb(V.GIVE, V.SGIVE))) {
        } else {
          g.PRSO = obj;
          if (hasFlag(obj, TRYTAKEBIT)) {
            taken = true;
          } else if (!(g.WINNER == PLAYER)) {
            taken = false;
          } else if (btst(ibits, STAKE) && eq(await ITAKE(false), true)) {
            taken = false;
          } else {
            taken = true;
          }
          if (taken && btst(ibits, SHAVE)) {
            if (1 < get(tbl, P_MATCHLEN)) {
              tell(S(g.NOT_HOLDING), " all those things!\n");
              return false;
            } else if (obj == NOT_HERE_OBJECT) {
              tell("[You can't see that here!]\n");
              return false;
            }
            if (g.WINNER == PLAYER) {
              tell(S(g.NOT_HOLDING));
            } else {
              tell("It doesn't look as if");
              await ARTICLE(g.WINNER, true);
              await PLURAL(g.WINNER);
              tell(" holding");
            }
            await ARTICLE(obj, true);
            g.P_IT_OBJECT = obj;
            tell(".\n");
            return false;
          } else if (!taken && (g.WINNER == PLAYER)) {
            tell("[taking");
            await ARTICLE(obj, true);
            tell(" first]\n");
          }
        }
      }
    }
  } else {
    return true;
  }
}

