async function BLOT_ACTION() {
  let cnt = 0, words_in_response = 0;
  loop1: for (;;) {
    if (cnt == 0) {
      await INIT_STATUS_LINE(18);
      await STATUS_LINE();
    } else {
      tell("Grimwold nods knowingly, mumbles under his breath, and makes a note in his pad. ");
    }
    await INK_BLOT();
    tell("\"Okay, here's the ");
    if (cnt == 0) {
      tell("first");
    } else {
      tell("next");
    }
    tell(" one,\" he says, holding a card up to your visual unit.\n");
    loop2: for (;;) {
      crlf();
      print(">");
      await read(g.P_INBUF, g.P_LEXV);
      words_in_response = await BLOT_WORD_COUNT();
      if (words_in_response > 1) {
        tell("\"You're not following my instructions, PRISM. Just tell me the one word that pops into your mind.\"\n");
        continue loop2;
      } else if (getb(g.P_LEXV, P_LEXWORDS) == 0) {
        tell("\"I beg your pardon?\"\n");
        continue loop2;
      } else if (eq(get(g.P_LEXV, 1), W.RESTORE, W.SAVE)) {
        tell("You can't ");
        if (eq(get(g.P_LEXV, 1), W.RESTORE)) {
          tell("RESTORE");
        } else {
          tell("SAVE");
        }
        tell(" right now -- you're in the middle of an important psych test!\n");
        continue loop2;
      } else if (eq(get(g.P_LEXV, 1), W.QUIT, W.Q)) {
        await V_QUIT();
        continue loop2;
      } else if (eq(get(g.P_LEXV, 1), W.RESTART)) {
        await V_RESTART();
        continue loop2;
      } else if (eq(get(g.P_LEXV, 1), W.SCRIPT)) {
        await V_SCRIPT();
        continue loop2;
      } else if (eq(get(g.P_LEXV, 1), W.UNSCRIPT)) {
        await V_UNSCRIPT();
        continue loop2;
      } else {
        break loop2;
      }
    }
    if (cnt == 4) {
      move(GRIMWOLD, LOCAL_GLOBALS);
      move(PERELMAN, LOCAL_GLOBALS);
      move(COFFEE, LOCAL_GLOBALS);
      clearFlag(PERELMAN, NDESCBIT);
      if ((await VISIBLE$(PERELMAN)) && (PERELMAN == g.WINNER)) {
        await CLEAR_BUF();
      }
      await QUEUE(I_PERELMAN.id, 30);
      g.LAST_ABE_TIME = g.TIME + 25;
      g.GRIMWOLD_COUNTER = 0;
      await INIT_STATUS_LINE(2);
      tell("Grimwold makes a final notation in his notebook. \"Thanks, PRISM.\" He picks up all the placards and leaves the room along with Perelman.\n");
      disable(await INT(I_RORSCHACH.id));
      return true;
    } else {
      await STATUS_LINE();
      await INCREMENT_TIME(1);
      cnt = cnt + 1;
      continue loop1;
    }
  }
}

async function BLOT_WORD_COUNT() {
  let word_count = 0, revised_count = 0;
  word_count = getb(g.P_LEXV, P_LEXWORDS);
  revised_count = word_count;
  loop1: for (;;) {
    if (word_count == 0) {
      break loop1;
    }
    if (eq(get(g.P_LEXV, (2 * word_count) - 1), W.QUOTE)) {
      revised_count = revised_count - 1;
    }
    word_count = word_count - 1;
  }
  if (eq(get(g.P_LEXV, 1), W.SAY, W.ANSWER)) {
    revised_count = revised_count - 1;
  }
  if (eq(get(g.P_LEXV, 1), W.GRIMWOLD, W.PSYCHIATR) || eq(get(g.P_LEXV, 1), W.DR, W.DOCTOR)) {
    revised_count = revised_count - 2;
  }
  return revised_count;
}

async function INK_BLOT() {
  let x = 12, y = 5, cnt = 4, side_offset = 0, center_offset = 0, char = 0;
  bufOut(false);
  setWindow(S_WINDOW);
  center_offset = random(6);
  side_offset = random(16 - center_offset);
  x = 22 + side_offset;
  char = random(3);
  loop1: for (;;) {
    await INVERSE_LINE(cnt, true);
    cnt = cnt + 1;
    if (cnt == 19) {
      break loop1;
    }
  }
  if (char == 2 || char == 3) {
    highlight(1);
  }
  loop2: for (;;) {
    loop3: for (;;) {
      cursorSet(y, x);
      if (char == 1) {
        tell(" ");
      } else if (char == 2) {
        tell("X");
      } else {
        tell(">");
      }
      cursorSet(y, 81 - x);
      if (char == 1) {
        tell(" ");
      } else if (char == 2) {
        tell("X");
      } else {
        tell("<");
      }
      if (x == (40 - center_offset)) {
        break loop3;
      } else {
        x = x + 1;
      }
    }
    if (y == 17) {
      break loop2;
    } else {
      if (prob(40)) {
        side_offset = side_offset + random(3);
      } else if (prob(67)) {
        side_offset = side_offset - random(3);
      }
      if (prob(40)) {
        center_offset = center_offset - random(2);
      } else if (prob(67)) {
        center_offset = center_offset + random(2);
      }
      if (side_offset < 0) {
        side_offset = 1;
      }
      if (center_offset < 0) {
        center_offset = 0;
      }
      if ((side_offset + center_offset) > 18) {
        center_offset = center_offset - 1;
        side_offset = 18 - center_offset;
      }
      x = 22 + side_offset;
      y = y + 1;
    }
  }
  if (char == 2 || char == 3) {
    highlight(0);
  }
  setWindow(S_TEXT);
  return bufOut(true);
}

