async function CLOTHES_F() {
  let garment = 0;
  if (isVerb(V.BUY)) {
    if (g.HERE == DUNBARS) {
      if (!(hasFlag(SWEATER, TRYTAKEBIT)) || !(loc(SCARF) == LOCAL_GLOBALS)) {
        return await CLOTHES_BUDGET();
      } else {
        if (g.SYEAR == 2041) {
          garment = SWEATER;
          tell("You look through many racks, finding nothing you like, and finally select a brightly colored myalon sweater that fits you perfectly");
        } else {
          garment = VEST;
          tell("After wincing at the prices, you pick out a thin, imitation wool vest");
        }
        if (await TOO_POOR(120, garment)) {
          return true;
        }
        if (g.SYEAR == 2041) {
          move(SWEATER, PLAYER);
          clearFlag(SWEATER, NDESCBIT);
          clearFlag(SWEATER, TRYTAKEBIT);
        } else {
          move(VEST, PLAYER);
          clearFlag(VEST, NDESCBIT);
          clearFlag(VEST, TRYTAKEBIT);
        }
        tell(". A clerk removes the anti-theft tag from the garment");
        await DEBIT(120);
        tell(".\n");
        return true;
      }
    } else if (g.HERE == HEIMAN_VILLAGE || g.HERE == ROCKVIL_MALL) {
      if ((g.STIME < 480) || (g.STIME > 1380)) {
        tell("Every store is closed for the night.\n");
        return true;
      } else if (!(hasFlag(SWEATER, TRYTAKEBIT)) || !(hasFlag(VEST, TRYTAKEBIT)) || !(loc(SCARF) == LOCAL_GLOBALS)) {
        await CLOTHES_BUDGET();
        return true;
      }
      putProp(SPEAR_CARRIER, P.SDESC, "clerk");
      tell("You enter a clothing store, but they have little that suits your taste. You finally pick out a conservative male scarf");
      if (await TOO_POOR(39, SCARF)) {
        tell("\nYou meekly leave the store.\n");
        return true;
      }
      move(SCARF, PLAYER);
      await DEBIT(39);
      tell(".\n");
      return true;
    } else {
      return await CANT_BUY(CLOTHES);
    }
  } else if (isVerb(V.TAKE, V.WEAR)) {
    if ((g.HERE == DUNBARS) && hasFlag(CLOTHES, TRYTAKEBIT)) {
      tell("You haven't paid for them.\n");
      return true;
    } else {
      tell("You're already wearing your clothes!\n");
      return true;
    }
  } else if (isVerb(V.REMOVE, V.TAKE_OFF)) {
    if (await IN_APARTMENT$()) {
      tell("You remove your clothes for a minute, but there's a bit of a chill in the air, so you decide to put them back on.\n");
      return true;
    } else {
      tell("You'd be arrested if you removed your clothes in public!\n");
      return true;
    }
  } else if (isVerb(V.EXAMINE)) {
    if (g.HERE == DUNBARS) {
      await PERFORM(V.EXAMINE, RACKS);
      return true;
    } else {
      await PERFORM(V.EXAMINE, ME);
      return true;
    }
  } else {
    return false;
  }
}

