async function I_MEAL() {
  let old_winner = 0;
  if (!(g.HERE == THE_COACHMAN || g.HERE == SIMONS)) {
    return false;
  }
  if (loc(CREDIT_CARD) == SPEAR_CARRIER) {
    move(CREDIT_CARD, PLAYER);
    if (g.CREDIT < 65) {
      tell("\nThe waiter returns with your card, informing you that you have insufficient funds to cover the meal. He escorts you out of the restaurant.\n\n");
      old_winner = g.WINNER;
      g.WINNER = PLAYER;
      await DO_WALK(P.OUT);
      return g.WINNER = old_winner;
    } else {
      if (g.RECORDING) {
        put(g.RECORDING_TABLE, 0, 1);
      }
      g.MEAL_STATUS = 6;
      await INCREMENT_TIME(12);
      tell("\nThe waiter places ");
      if (g.SYEAR == 2041) {
        tell("your soybean salad on the table. A generous portion, and quite tasty; you quickly devour it");
      } else {
        tell("your kelp fillet in front of you. You eat the entire dish, and while it was tasty, you still feel that it wasn't worth the price");
      }
      await DEBIT(65);
      tell(".\n");
      return true;
    }
  } else if (g.MEAL_STATUS == 4) {
    g.WAITER_COUNTER = g.WAITER_COUNTER + 1;
    await QUEUE(I_MEAL.id, 1);
    if (g.WAITER_COUNTER == 4) {
      tell("\nThe waiter clears his throat. \"If you're unable to produce your credit card, I'd be glad to ask the maitre d' over here to assist you.\"\n");
      return true;
    } else if (g.WAITER_COUNTER == 6) {
      tell("\nThe waiter, looking quite annoyed, leaves the tableside. A moment later, the maitre d' arrives and shows you out of the restaurant.\n\n");
      old_winner = g.WINNER;
      g.WINNER = PLAYER;
      await DO_WALK(P.OUT);
      g.WINNER = old_winner;
      return M_FATAL;
    } else {
      g.P_IT_OBJECT = SPEAR_CARRIER;
      tell("\nThe waiter is standing at your table, waiting for your ");
      printD(CREDIT_CARD);
      tell(".\n");
      return true;
    }
  } else if (eq(loc(PLAYER), RESTAURANT_TABLE)) {
    g.P_IT_OBJECT = SPEAR_CARRIER;
    g.MEAL_STATUS = 4;
    tell("\nThe waiter hands you a ");
    if (g.STIME < 690) {
      tell("breakfast");
    } else if (g.STIME > 960) {
      tell("dinner");
    } else {
      tell("lunch");
    }
    tell(" menu, and after perusing the meat prices you settle on a");
    if (g.SYEAR == 2041) {
      tell(" nice, reasonably priced soybean salad");
    } else {
      tell("n overpriced kelp fillet, the cheapest item on the menu");
    }
    tell(". The waiter jots down your order, and reminds you of the restaurant's policy of payment in advance.\n");
    return await QUEUE(I_MEAL.id, 1);
  } else {
    await QUEUE(I_MEAL.id, 1);
    return false;
  }
}

