async function TUBE_JUNCTION_F(rarg) {
  let red = false, brown = false, both = false, x = false;
  if (rarg == M_LOOK) {
    tell("You are on a central platform between four sets of tracks. On the wall is a sign, in brown and red:\n");
    await PERFORM(V.READ, TUBE_SIGN);
    tell("Tracks for the Brownline tubecars lie to the southeast and northwest. Another pair of tracks, for the Redline, lie down some steps to the southwest and northeast. A stairway leads up out of the station.");
    return true;
  } else if (rarg == M_END) {
    if (isVerb(V.LOOK, V.SAVE)) {
      x = true;
    } else if (!(g.HERE == g.L_HERE)) {
      x = true;
    }
    if (!x) {
      return false;
    }
    if (loc(RED_TUBECAR_OBJECT) == g.HERE) {
      red = true;
    }
    if (loc(BROWN_TUBECAR_OBJECT) == g.HERE) {
      brown = true;
      if (red) {
        both = true;
      }
    }
    if (!(red || brown)) {
      return false;
    } else {
      if (both) {
        tell("Tubecars are");
      } else {
        tell("A tubecar is");
      }
      tell(" sitting on the tracks to the ");
      if (brown) {
        if (g.BROWN_NORTHBOUND) {
          tell("southeast");
        } else {
          tell("northwest");
        }
      }
      if (both) {
        tell(" and ");
      }
      if (red) {
        if (g.RED_NORTHBOUND) {
          tell("northeast");
        } else {
          tell("southwest");
        }
      }
      tell(".\n");
      return true;
    }
  } else {
    return false;
  }
}

