async function V_LOOK_INSIDE() {
  if (await UNSEEABLE_OBJECT()) {
    return true;
  } else if (hasFlag(g.PRSO, ACTORBIT)) {
    tell("There is nothing special to be seen.\n");
    return true;
  } else if (hasFlag(g.PRSO, DOORBIT)) {
    tell("All you can tell is that");
    await ARTICLE(g.PRSO, true);
    await PLURAL(g.PRSO);
    if (hasFlag(g.PRSO, OPENBIT)) {
      tell(" open.\n");
      return true;
    } else {
      tell(" closed.\n");
      return true;
    }
  } else if (hasFlag(g.PRSO, VEHBIT)) {
    if ((g.PRSO == COUCH) && (loc(JILL) == g.HERE) && ((g.JILL_COUNTER == 4 || g.JILL_COUNTER == 10) || (g.SYEAR == 2071))) {
      return await JILL_DESCFCN();
    } else if ((g.PRSO == BED) && (loc(JILL) == g.HERE) && ((g.JILL_COUNTER == 0 || g.JILL_COUNTER == 12) || (g.SYEAR == 2061))) {
      return await JILL_DESCFCN();
    } else if ((g.PRSO == SEAT) && (g.HERE == SKYCAB)) {
      return await JILL_DESCFCN();
    } else if (g.PRSO == loc(PLAYER)) {
      return await DESCRIBE_VEHICLE();
    } else {
      tell("You see nothing special.\n");
      return true;
    }
  } else if (hasFlag(g.PRSO, SURFACEBIT)) {
    if (first(g.PRSO)) {
      return await PRINT_CONT(g.PRSO);
    } else {
      tell("There is nothing on");
      await ARTICLE(g.PRSO, true);
      tell(".\n");
      return true;
    }
  } else if (hasFlag(g.PRSO, CONTBIT)) {
    if (await SEE_INSIDE$(g.PRSO)) {
      if (first(g.PRSO)) {
        return await PRINT_CONT(g.PRSO);
      } else {
        tell("It's empty.\n");
        return true;
      }
    } else if (!(hasFlag(g.PRSO, OPENBIT)) && first(g.PRSO)) {
      await PERFORM(V.OPEN, g.PRSO);
      return true;
    } else {
      tell("It seems that");
      await ARTICLE(g.PRSO, true);
      tell(" is closed.\n");
      return true;
    }
  } else {
    tell("You can't do that.\n");
    return true;
  }
}

