async function V_PUT() {
  let cont_closed = false;
  if ((g.PRSO == HEADSET) && (g.PRSI == HEAD || g.PRSI == ME)) {
    await PERFORM(V.WEAR, HEADSET);
    return true;
  } else if (!(hasFlag(g.PRSI, OPENBIT)) && !(hasFlag(g.PRSI, DOORBIT)) && !(hasFlag(g.PRSI, CONTBIT)) && !(hasFlag(g.PRSI, SURFACEBIT)) && !(hasFlag(g.PRSI, VEHBIT))) {
    tell("You can't put");
    await ARTICLE(g.PRSO, true);
    tell(" in");
    await ARTICLE(g.PRSI);
    tell("!\n");
    return true;
  } else if ((g.PRSI == g.PRSO) || ((await HELD$(g.PRSO)) && !(hasFlag(g.PRSO, TAKEBIT)))) {
    tell("How can you do that?\n");
    return true;
  } else if (loc(g.PRSO) == g.PRSI) {
    tell("I think");
    await ARTICLE(g.PRSO, true);
    tell(" is already in");
    await ARTICLE(g.PRSI, true);
    tell(".\n");
    return true;
  } else if (!(hasFlag(g.PRSI, OPENBIT)) && !(hasFlag(g.PRSI, SURFACEBIT))) {
    cont_closed = true;
  }
  if ((((await WEIGHT(g.PRSI)) + getProp(g.PRSO, P.SIZE)) - getProp(g.PRSI, P.SIZE)) > getProp(g.PRSI, P.CAPACITY)) {
    if (hasFlag(g.PRSI, VEHBIT)) {
      return await V_YELL();
    } else {
      if (cont_closed) {
        setFlag(g.PRSI, OPENBIT);
        tell("You open");
        await ARTICLE(g.PRSI, true);
        tell(" and discover that t");
      } else {
        tell("T");
      }
      tell("here's not enough room inside.\n");
      return true;
    }
  } else if (!(await HELD$(g.PRSO)) && eq(await ITAKE(), M_FATAL, false)) {
    return true;
  } else {
    move(g.PRSO, g.PRSI);
    setFlag(g.PRSO, TOUCHBIT);
    if (g.PRSI == BUREAU) {
      tell("You put");
      await ARTICLE(g.PRSO, true);
      tell(" on the bureau.\n");
      return true;
    } else {
      tell("Done");
      if (cont_closed) {
        setFlag(g.PRSI, OPENBIT);
        tell(" (after opening");
        await ARTICLE(g.PRSI, true);
        tell(", of course)");
      }
      tell(".\n");
      return true;
    }
  }
}

