async function V_WALK() {
  let pt = 0, pts = 0, str = 0, obj = 0, rm = 0;
  if (!g.PRSO) {
    return await V_WALK_AROUND();
  } else if (!g.P_WALK_DIR) {
    await PERFORM(V.WALK_TO, g.PRSO);
    return true;
  } else if (pt = getPropAddr(g.HERE, g.PRSO)) {
    if (eq(pts = propSize(pt), UEXIT)) {
      return await GOTO(get(pt, REXIT));
    } else if (pts == NEXIT) {
      tell(S(get(pt, NEXITSTR)), "\n");
      return M_FATAL;
    } else if (pts == FEXIT) {
      if (rm = await apply(get(pt, FEXITFCN))) {
        return await GOTO(rm);
      } else {
        return M_FATAL;
      }
    } else if (pts == CEXIT) {
      if (globalValue(getb(pt, CEXITFLAG))) {
        return await GOTO(get(pt, REXIT));
      } else if (str = get(pt, CEXITSTR)) {
        tell(S(str), "\n");
        return M_FATAL;
      } else {
        tell(S(g.CANT_GO), "\n");
        return M_FATAL;
      }
    } else if (pts == DEXIT) {
      if (hasFlag(obj = get(pt, DEXITOBJ), OPENBIT)) {
        return await GOTO(get(pt, REXIT));
      } else if (str = get(pt, DEXITSTR)) {
        tell(S(str), "\n");
        g.P_IT_OBJECT = obj;
        return M_FATAL;
      } else {
        tell("The ");
        await DPRINT(obj);
        tell(" is closed.\n");
        g.P_IT_OBJECT = obj;
        return M_FATAL;
      }
    } else {
      return false;
    }
  } else {
    if (g.PRSO == P.OUT || g.PRSO == P.IN) {
      await V_WALK_AROUND();
    } else if (g.SIMULATING) {
      tell(S(g.CANT_GO), "\n");
    } else {
      g.YES_NO_FLAG = 4;
      await QUEUE(I_YES_NO.id, 2);
      tell("You're an immobile computer, remember?\n");
    }
    return M_FATAL;
  }
}

