async function DESCRIBE_OBJECT(obj, v$, level) {
  let str = false, av = 0;
  if ((level == 0) && (await apply(getProp(obj, P.DESCFCN), M_OBJDESC))) {
    return true;
  } else if ((level == 0) && ((!(hasFlag(obj, TOUCHBIT)) && (str = getProp(obj, P.FDESC))) || (str = getProp(obj, P.LDESC)))) {
    tell(S(str));
  } else if (level == 0) {
    tell("There");
    await PLURAL(obj);
    await ARTICLE(obj);
    tell(" here.");
  } else {
    tell(S(get(g.INDENTS, level)));
    if (hasFlag(obj, NARTICLEBIT)) {
    } else if (hasFlag(obj, VOWELBIT)) {
      tell("an ");
    } else {
      tell("a ");
    }
    await DPRINT(obj);
    if (hasFlag(obj, WORNBIT)) {
      tell(" (being worn)");
    }
  }
  crlf();
  if ((await SEE_INSIDE$(obj)) && first(obj)) {
    return await PRINT_CONT(obj, v$, level);
  } else {
    return false;
  }
}

async function PRINT_CONT(obj, v$ = false, level = 0) {
  let y = 0, _1st$ = true, av = false, str = 0, pv$ = false, inv$ = false;
  if (!(y = first(obj))) {
    return true;
  }
  if (hasFlag(loc(g.WINNER), VEHBIT)) {
    av = loc(g.WINNER);
  }
  if (PLAYER == obj || PLAYER == loc(obj)) {
    inv$ = true;
  } else {
    for (;;) {
      if (!y) {
        return !_1st$;
      } else if (y == av) {
        pv$ = true;
      } else if (y == g.WINNER) {
      } else if (!(hasFlag(y, INVISIBLE)) && !(hasFlag(y, TOUCHBIT)) && (str = getProp(y, P.FDESC))) {
        if (!(hasFlag(y, NDESCBIT))) {
          tell(S(str), "\n");
        }
        if ((await SEE_INSIDE$(y)) && !(getProp(loc(y), P.DESCFCN)) && first(y)) {
          await PRINT_CONT(y, v$, 0);
        }
      }
      y = next(y);
    }
  }
  y = first(obj);
  for (;;) {
    if (!y) {
      if (pv$ && av && first(av)) {
        await PRINT_CONT(av, v$, level);
      }
      return !_1st$;
    } else if (y == av || y == PLAYER) {
    } else if (!(hasFlag(y, INVISIBLE)) && (inv$ || hasFlag(y, TOUCHBIT) || !(getProp(y, P.FDESC)))) {
      if (!(hasFlag(y, NDESCBIT))) {
        if (_1st$) {
          if (await FIRSTER(obj, level)) {
            if (level < 0) {
              level = 0;
            }
          }
          level = 1 + level;
          _1st$ = false;
        }
        await DESCRIBE_OBJECT(y, v$, level);
      } else if (first(y) && (await SEE_INSIDE$(y))) {
        await PRINT_CONT(y, v$, level);
      }
    }
    y = next(y);
  }
}

async function PRINT_CONTENTS(obj) {
  let f = 0, n_ = 0, _1st$ = true, it$ = false, two$ = false;
  if (f = first(obj)) {
    for (;;) {
      n_ = next(f);
      if (_1st$) {
        _1st$ = false;
      } else {
        tell(",");
        if (!n_) {
          tell(" and");
        }
      }
      await ARTICLE(f);
      if (!it$ && !two$) {
        it$ = f;
      } else {
        two$ = true;
        it$ = false;
      }
      f = n_;
      if (!f) {
        if (it$ && !two$) {
          g.P_IT_OBJECT = it$;
        }
        return true;
      }
    }
  } else {
    return false;
  }
}

