async function ROB(who, where) {
  let n_ = 0, x = 0;
  x = first(who);
  for (;;) {
    if (!x) {
      return true;
    }
    n_ = next(x);
    if ((who == PLAYER) && hasFlag(x, WORNBIT)) {
      clearFlag(x, WORNBIT);
    }
    move(x, where);
    x = n_;
  }
}

