async function NOT_HERE_OBJECT_F() {
  let tbl = 0, prso$ = true, obj = 0, x = false;
  if ((g.PRSO == NOT_HERE_OBJECT) && (g.PRSI == NOT_HERE_OBJECT)) {
    tell("[Those things aren't here!]\n");
    return true;
  } else if (g.PRSO == NOT_HERE_OBJECT) {
    tbl = g.P_PRSO;
  } else {
    tbl = g.P_PRSI;
    prso$ = false;
  }
  if ((prso$ && (await PRSO_VERB$())) || (!prso$ && (await PRSI_VERB$())) || (!prso$ && !(g.WINNER == PLAYER) && isVerb(V.SGIVE) && (g.PRSO == ME))) {
    x = true;
    if (obj = await FIND_NOT_HERE(tbl, prso$)) {
      if (!(obj == NOT_HERE_OBJECT)) {
        return true;
      }
    } else {
      return false;
    }
  }
  if (x) {
    tell("[You'll have to be more specific.]\n");
  } else if (isVerb(V.TELL, V.CALL) && (g.P_XNAM == W.JILL) && (await IN_APARTMENT$()) && !(loc(JILL) == LOCAL_GLOBALS)) {
    if (g.SYEAR == 2041 || g.SYEAR == 2051) {
      tell("\"I can't hear you, Perry!\" Jill shouts back. \"Come in here!\"\n");
    } else {
      tell("There's no reply; perhaps Jill didn't hear you from the other room.\n");
    }
  } else if (g.WINNER == PLAYER) {
    tell("[You can't ");
    if (g.P_XNAM == W.CONVERSAT || g.P_XNAM == W.ALARM || g.P_XNAM == W.MUSIC) {
      tell("hear");
    } else {
      tell("see");
    }
    if (!(await NAME$(g.P_XNAM)) && !(g.P_XADJ == W.MY)) {
      tell(" any");
    } else if (g.P_XNAM == W.WIZARD || g.P_XNAM == W.OZ) {
      tell(" any");
    }
    await NOT_HERE_PRINT(prso$);
    tell(" here!]\n");
  } else {
    if (g.MODE == INTERFACE_MODE) {
      tell("Emitting signals of confusion,");
    } else {
      tell("Looking confused,");
    }
    await ARTICLE(g.WINNER, true);
    if (g.MODE == INTERFACE_MODE) {
      tell(" reports, \"This unit is unaware of");
    } else {
      tell(" says, \"I don't see");
    }
    if (!(await NAME$(g.P_XNAM))) {
      tell(" any");
    }
    await NOT_HERE_PRINT(prso$);
    tell(" here!\"\n");
  }
  await CLEAR_BUF();
  return true;
}

