async function INIT_STATUS_LINE(height, dont_clear = false) {
  if (!dont_clear) {
    clearScreen(-1);
    splitWindow(height);
  }
  g.L_HERE = false;
  g.L_MODE = false;
  g.L_DATE = false;
  setWindow(S_WINDOW);
  bufOut(false);
  if (height == 7) {
    return true;
  }
  await INVERSE_LINE(1);
  await INVERSE_LINE(2);
  highlight(1);
  cursorSet(1, 2);
  tell("Mode:");
  cursorSet(1, 60);
  tell("Time:");
  cursorSet(2, 2);
  tell("Location:");
  cursorSet(2, 60);
  tell("Date:");
  highlight(0);
  bufOut(true);
  return setWindow(S_TEXT);
}

async function INVERSE_LINE(line_number, center_half = false) {
  if (center_half) {
    cursorSet(line_number, 21);
  } else {
    cursorSet(line_number, 1);
  }
  highlight(1);
  loop1: for (;;) {
    tell("                                       ");
    if (center_half) {
      break loop1;
    } else {
      center_half = true;
    }
  }
  return highlight(0);
}

async function PRINT_SPACES(cnt) {
  for (;;) {
    if ((cnt = cnt - 1) < 0) {
      return true;
    } else {
      printC(32);
    }
  }
}

async function CONTINUE() {
  let currently_scripting = false, cnt = 0;
  if (getb(0, 32) > 21) {
    cnt = getb(0, 32) - 21;
    loop1: for (;;) {
      cnt = cnt - 1;
      crlf();
      if (cnt == 0) {
        break loop1;
      }
    }
  }
  if (btst(get(0, 8), 1)) {
    currently_scripting = true;
    dirOut(D_PRINTER_OFF);
  }
  tell("[Hit any key to continue.]");
  bufOut(false);
  bufOut(true);
  if (currently_scripting) {
    dirOut(D_PRINTER_ON);
  }
  return await readChar(1);
}

async function STATUS_LINE() {
  let len = 0, location = 0;
  bufOut(false);
  setWindow(S_WINDOW);
  highlight(1);
  if (!(g.MODE == g.L_MODE) || (g.RECORDING && !g.L_RECORDING) || (g.L_RECORDING && !g.RECORDING)) {
    dirOut(D_SCREEN_OFF);
    dirOut(D_TABLE_ON, g.SL_BUFFER);
    await DPRINT(g.MODE);
    if (g.RECORDING) {
      tell(" (recording)");
    }
    dirOut(D_TABLE_OFF);
    dirOut(D_SCREEN_ON);
    len = get(g.SL_BUFFER, 0);
    cursorSet(1, 9);
    await DPRINT(g.MODE);
    if (g.RECORDING) {
      g.L_RECORDING = true;
      tell(" (recording)");
    } else {
      g.L_RECORDING = false;
    }
    g.L_MODE = g.MODE;
    await PRINT_SPACES(33 - len);
  }
  cursorSet(1, 67);
  if (g.SIMULATING) {
    await TIME_PRINT(g.STIME);
  } else {
    await TIME_PRINT(g.TIME);
  }
  await PRINT_SPACES(3);
  if ((g.CURRENT_FILE && !(g.L_HERE == g.CURRENT_DIRECTORY)) || (!g.CURRENT_FILE && !(g.L_HERE == g.HERE))) {
    cursorSet(2, 13);
    dirOut(D_SCREEN_OFF);
    dirOut(D_TABLE_ON, g.SL_BUFFER);
    if (g.CURRENT_FILE) {
      location = g.CURRENT_DIRECTORY;
    } else {
      location = g.HERE;
    }
    await DPRINT(location);
    g.L_HERE = location;
    dirOut(D_TABLE_OFF);
    dirOut(D_SCREEN_ON);
    len = get(g.SL_BUFFER, 0);
    await DPRINT(location);
    await PRINT_SPACES(29 - len);
  }
  if (g.SIMULATING && !(g.SDATE == g.L_DATE)) {
    cursorSet(2, 67);
    tell(N(g.SMONTH), "/", N(g.SDATE), "/", N(g.SYEAR));
    g.L_DATE = g.SDATE;
    await PRINT_SPACES(3);
  } else if (!g.SIMULATING && !(g.DATE == g.L_DATE)) {
    cursorSet(2, 67);
    tell(N(g.MONTH), "/", N(g.DATE), "/", N(g.YEAR));
    g.L_DATE = g.DATE;
    await PRINT_SPACES(3);
  }
  setWindow(S_TEXT);
  highlight(0);
  return bufOut(true);
}

async function TIME_PRINT(tm, skip_am_pm = false) {
  let hr = 0;
  if (tm > 1440) {
    tm = tm - 1440;
  }
  hr = div(tm, 60);
  if (hr > 12) {
    hr = hr - 12;
  }
  if (hr == 0) {
    tell("12");
  } else {
    printN(hr);
  }
  tell(":");
  hr = mod(tm, 60);
  if (hr < 10) {
    tell("0");
  }
  tell(N(hr));
  if (skip_am_pm) {
    return true;
  }
  return await AM_PM_PRINT(tm);
}

async function JUSTIFY_TIME_PRINT(num) {
  if ((num > 59) && (num < 600)) {
    tell(" ");
  } else if ((num < 1320) && (num > 779)) {
    tell(" ");
  }
  return await TIME_PRINT(num, true);
}

async function AM_PM_PRINT(num) {
  if ((num < 720) || (num == 1440)) {
    tell("am");
    return true;
  } else {
    tell("pm");
    return true;
  }
}

