async function SCORE(num) {
  let val = 0;
  if (!g.RECORDING) {
    return true;
  }
  val = get(g.SCORE_TABLE, num);
  put(g.SCORE_TABLE, num, 0);
  if (g.SYEAR == 2051) {
    return g._2051_SCORE = g._2051_SCORE + val;
  } else if (g.SYEAR == 2061) {
    return g._2061_SCORE = g._2061_SCORE + val;
  } else if (g.SYEAR == 2071) {
    return g._2071_SCORE = g._2071_SCORE + val;
  } else if (g.SYEAR == 2081) {
    return g._2081_SCORE = g._2081_SCORE + val;
  } else {
    return false;
  }
}

