async function I_FIRST_SIMULATION_RESULT() {
  let cnt = 0, num = 0;
  if (g.COMPLETED_TASKS) {
    tell("Bug #3K\n");
    return false;
  }
  putProp(RECORD_BUFFER, P.SIZE, 0);
  g.RECORDINGS_INCLUDE_SIMULATION = false;
  if (!(await PERELMAN_SHARE(I_FIRST_SIMULATION_RESULT.id))) {
    return false;
  }
  disable(await INT(I_MESSAGE_E.id));
  g.MESSAGE_E_COUNTER = 0;
  loop1: for (;;) {
    if (eq(get(g.RECORDING_TABLE, cnt), 1)) {
      num = num + 1;
    }
    cnt = cnt + 2;
    if (cnt > 16) {
      break loop1;
    }
  }
  if (num == 9) {
    move(PERELMAN, LOCAL_GLOBALS);
    move(COFFEE, LOCAL_GLOBALS);
    if ((await VISIBLE$(PERELMAN)) && (PERELMAN == g.WINNER)) {
      await CLEAR_BUF();
    }
    g.LAST_ABE_TIME = g.TIME + 55;
    await QUEUE(I_PERELMAN.id, 60);
    g.COMPLETED_TASKS = true;
    tell(", smiling. \"An excellent job, PRISM. We just finished viewing your recordings, and the experts were quite pleased.\" He pauses, as though realizing something for the first time. \"In fact, I thought they looked pretty good myself. I suppose this means the Plan'll get adopted.\n\n\"What's next for you, I wonder? You're going to be a hero, you know. You'd probably get a call from the President congratulating you, except of course that he's against the Plan.\" Perelman notices a paper on his desk. \"Oh, apparently the ");
    printD(SIMULATION_CONTROLLER);
    tell(" generated a lot of new data correlations while running your simulation. I'm not sure what the effect of that will be. Might make an even more accurate simulation possible.\n\n\"Well, I've got another meeting now, as usual. But once again, thanks for not letting me down.\" Perelman leaves.");
    await CONTINUE();
    g.MODE = COMM_MODE;
    g.HERE = COMM_ROOM;
    move(PLAYER, COMM_ROOM);
    await INCREMENT_TIME(680);
    await QUEUE(I_MESSAGE_X.id, 12);
    await QUEUE(I_MESSAGE_Q.id, 77);
    await CHAPTER_PRINT(2);
    tell("\n\n\n");
    await PRINT_SPACES(21);
    tell("\"Deep into that darkness peering,\n");
    await PRINT_SPACES(27);
    tell("long I stood there, wondering, fearing,\n");
    await PRINT_SPACES(22);
    tell("Doubting, dreaming dreams no mortal\n");
    await PRINT_SPACES(27);
    tell("ever dared to dream before.\"\n");
    await PRINT_SPACES(40);
    tell("-- Edgar Allan Poe\n\n\n\n");
    await CONTINUE();
    await INIT_STATUS_LINE(2);
    return await V_LOOK();
  } else if (num == 8) {
    await QUEUE(I_MESSAGE_M.id, 875);
    putProp(MESSAGE_M, P.CAPACITY, 1);
    tell(". \"PRISM. Uh, overall, a fine job in the simulation. I hate to be a ");
    (await ITALICIZE("noodge", true));
    tell(", but we just finished viewing the recordings, and there's one omission. Uh, let's see. Oh, right. ");
    cnt = 0;
    loop2: for (;;) {
      if (eq(get(g.RECORDING_TABLE, cnt), 0)) {
        tell(S(get(g.RECORDING_TABLE, cnt + 1)));
        break loop2;
      }
      cnt = cnt + 2;
    }
    g.YES_NO_FLAG = 6;
    await QUEUE(I_YES_NO.id, 2);
    tell(". Could you, ah, go back into ");
    printD(SIMULATION_MODE);
    tell(" and make that one additional recording?\"\n");
    return true;
  } else {
    await QUEUE(I_MESSAGE_M.id, 875);
    putProp(MESSAGE_M, P.CAPACITY, 1);
    move(PERELMAN, LOCAL_GLOBALS);
    move(COFFEE, LOCAL_GLOBALS);
    if ((await VISIBLE$(PERELMAN)) && (PERELMAN == g.WINNER)) {
      await CLEAR_BUF();
    }
    await QUEUE(I_PERELMAN.id, 60);
    g.LAST_ABE_TIME = g.TIME + 55;
    tell(". He looks unhappy. \"PRISM, you didn't record ");
    if (num == 0) {
      tell("any");
    } else {
      tell("some");
    }
    tell(" of the events the experts asked you for.\" He picks up a piece of paper from his desk. \"Let's see. ");
    cnt = 0;
    loop3: for (;;) {
      if (eq(get(g.RECORDING_TABLE, cnt), 0)) {
        tell(S(get(g.RECORDING_TABLE, cnt + 1)), ". ");
      }
      cnt = cnt + 2;
      if (cnt > 16) {
        break loop3;
      }
    }
    tell("Please go back into ");
    printD(SIMULATION_MODE);
    tell(" and make these recordings.\" Perelman lowers his eyes. \"Please don't let me down, PRISM.\" He walks out of the office.\n");
    return true;
  }
}

async function PERELMAN_SHARE(interrupt) {
  let saw_enter = false;
  if (!(loc(PERELMAN) == OFFICE)) {
    move(PERELMAN, OFFICE);
    putProp(PERELMAN, P.LDESC, "Perelman is sitting at his desk, absent-mindedly playing with a pencil.");
    if (g.HERE == OFFICE) {
      saw_enter = true;
      tell("\nPerelman walks into the office and", S(g.SPOTS_ACTIVE_LIGHT), " immediately. \"Hello, PRISM,\" he says, sitting down at his desk. \"", S(g.IT_LOOKS_LIKE), " you beat me here. Give me a moment, please.\" He begins quickly jotting a few notes onto a pad.\n");
    } else {
      await QUEUE(interrupt, 1);
      return false;
    }
  } else if (!(g.HERE == OFFICE)) {
    await QUEUE(interrupt, 1);
    return false;
  }
  tell("\nPerelman looks up");
  g.REVIEWING_RECORDINGS = false;
  if (!saw_enter) {
    tell(",", S(g.SPOTS_ACTIVE_LIGHT), ", and nods toward your comm outlet");
  }
  return true;
}

async function PERELMAN_F() {
  if (g.WINNER == PERELMAN) {
    if (loc(RYDER) == OFFICE) {
      g.WINNER = PLAYER;
      await PERFORM(V.TELL, RYDER);
      g.WINNER = PERELMAN;
      return await CLEAR_BUF();
    } else if (await QUEUED$(I_FIRST_SIMULATION_RESULT.id)) {
      g.WINNER = PLAYER;
      await I_FIRST_SIMULATION_RESULT();
      disable(await INT(I_FIRST_SIMULATION_RESULT.id));
      return await CLEAR_BUF();
    } else if (await QUEUED$(I_RECORDINGS_VIEWED.id)) {
      g.WINNER = PLAYER;
      await I_RECORDINGS_VIEWED();
      return await CLEAR_BUF();
    } else if ((g.GRIMWOLD_COUNTER > 0) && isVerb(V.YES)) {
      g.WINNER = PLAYER;
      await BLOT_ACTION();
      return await CLEAR_BUF();
    } else if ((g.GRIMWOLD_COUNTER > 0) && isVerb(V.NO)) {
      g.WINNER = PLAYER;
      await V_NO();
      return await CLEAR_BUF();
    } else if (loc(GRIMWOLD) == g.HERE) {
      g.WINNER = PLAYER;
      await PERFORM(V.TELL_ABOUT, PERELMAN, RECORD_BUFFER);
      return await CLEAR_BUF();
    } else if (isVerb(V.EXAMINE, V.READ) && (g.PRSO == RECORD_BUFFER)) {
      g.WINNER = PLAYER;
      await PERFORM(V.TELL_ABOUT, PERELMAN, RECORD_BUFFER);
      g.WINNER = PERELMAN;
      return true;
    } else if (isVerb(V.WHO, V.WHAT)) {
      await PERFORM(V.TELL_ABOUT, ME, g.PRSO);
      return true;
    } else if (isVerb(V.TELL_ABOUT) && (g.PRSO == ME)) {
      if (g.PRSI == MY_NAME) {
        tell("Perelman looks thoughtful. \"I never mentioned where 'PRISM' comes from? There are so many things I want to talk to you about; perhaps, soon, I'll have more time...\n\n\"Well, officially it's an acronym for Perelman-Randu Introductory Soliptic Machine. But we came up with that only after I'd already named you PRISM. It actually comes from a couple of different poems -- I think they're in a file somewhere in your ");
        printD(LIBRARY_MODE);
        tell(".\"\n");
        return true;
      } else if (g.PRSI == PERELMAN || g.PRSI == YOURSELF) {
        tell("Perelman looks introspective and twiddles a pencil around aimlessly. \"I guess you'd have to say I'm a dreamer, a bit of an idealist. Politically, I've always been pretty liberal. My genuine sense of the humorous side of life was instilled in me, along with the rest of my Jewish heritage, by my grandfather -- my mother's father.\n\n\"I married a wonderful woman, Leah, a frail little thing who left me a widower after giving birth to our daughter, Esther. She's been a wonderful daughter; I've always been incredibly proud of her.\n\n\"Since Leah died, my life has been divided between raising Esther and my work at the University, and more recently here at the Project. And lately, now that Esther's out on her own, my work has been most of my life.\"\n");
        return true;
      } else if (g.PRSI == ESTHER) {
        tell("\"Esther is my daughter, my only child. A sweeter and more loving child no man could ask for.\"\n");
        return true;
      } else if (g.PRSI == GRIMWOLD) {
        tell("\"Grimwold is the head of the psychological team. He helped me design a lot of your 'life.' You've met him -- he gave you those Rorschach tests.\"\n");
        return true;
      } else if (g.PRSI == PLAN) {
        tell("\"The Plan. Its full name is the Plan for Renewed National Purpose, a typical bit of linguistic obfuscation. A group of politicians and businessmen are trying to take advantage of the clamor for change, any kind of change.\"\n");
        return true;
      } else if (g.PRSI == RYDER) {
        tell("\"Ryder's a Senator from...I'm not sure. Oklahoma? Alabama? Anyway, he's one of the big driving forces behind the Plan. Gives speeches about it all the time. He introduced the bill to Congress. He's really photogenic, very popular. I've got sort of mixed feelings about him.\"\n");
        return true;
      } else if (g.PRSI == RANDU) {
        tell("\"Aseejh and I have been working together since we met at Rockvil U. nearly twenty years ago. He did virtually all of the technical design that made you possible. He's a terrific guy. I've been meaning to get you a communications outlet in his office -- I think you'd be good friends.\"\n");
        return true;
      } else if (g.PRSI == GOLD) {
        tell("\"Vera Gold is the Chief Administrator for the entire PRISM Project. She was one of the conditions for getting federal funding several years ago. A more officious and incompetent woman has yet to be born. Her only talent is making herself look good.\n\n\"Technically, she's my boss, but I've tried to distance the research team from her as much as possible. It's been getting more and more difficult, though.\"\n");
        return true;
      } else if (g.PRSI == PRICE) {
        tell("\"Alyson? She's my administrative assistant. I can't say enough good things about her.\"\n");
        return true;
      } else if (g.PRSI == FORTZMAN) {
        tell("\"Fortzman...");
        printD(FORTZMAN);
        tell("...the name is vaguely familiar. I think she heads some prestigious conservative think-tank out on the west coast.\"\n");
        return true;
      } else if (g.PRSI == WARREN) {
        tell("Perelman knits his brow. \"The name is familiar. I hope I'm not going senile...oh, right! ");
        printD(WARREN);
        tell(" is in charge of your peripheral devices. If they ever decide to tack any more computers onto you, you'll probably find out about it from her.\"\n");
        return true;
      } else if (g.PRSI == RESIGNATION) {
        tell("\"Oh, ever since Vera Gold became Project Administrator, I threaten to resign about twice a week, just to keep her honest. I've never actually gone through with it, of course.\"\n");
        return true;
      } else if (g.PRSI == MINDEX) {
        tell("\"It's some sort of new narcotic that's supposed to be completely safe and nonaddictive. You're really asking the wrong person -- I'm pretty square when it comes to drugs and stuff.\"\n");
        return true;
      } else if (g.PRSI == CLERKMATON) {
        tell("\"They're the latest fad in retailing -- cute, little robot clerks. I don't think they'll catch on. Of course, I said the same thing about joybooths.\"\n");
        return true;
      } else if (g.PRSI == PARENTS || g.PRSI == CLAVE || g.PRSI == RAV || g.PRSI == FYLA) {
        tell("\"Everyone from your simulated childhood was just a composite, not based on anyone specifically.");
        if (g.PRSI == PARENTS) {
          tell(" You don't have any real parents, of course, unless you want to count Aseejh and myself.");
        }
        tell("\"\n");
        return true;
      } else if (g.PRSI == CC_PRINTOUT) {
        tell("\"Nothing important.\"\n");
        return true;
      } else if (g.PRSI == SILVER_DOVE) {
        tell("\"Never heard of it.\"\n");
        return true;
      } else {
        tell("\"I don't know what I could tell you that you don't already know...\"\n");
        return true;
      }
    } else if (isVerb(V.YES) && (g.YES_NO_FLAG == 6)) {
      return await V_YES();
    } else if (isVerb(V.NO) && (g.YES_NO_FLAG == 6)) {
      return await V_NO();
    } else {
      tell("Perelman smiles warmly. \"PRISM, I'd love to chat, but I've got a stack of paperwork you could lose a skybus in.\"\n");
      return await CLEAR_BUF();
    }
  } else if (isVerb(V.THANK)) {
    if (loc(RYDER) == OFFICE) {
      await PERFORM(V.TELL, RYDER);
      return true;
    } else {
      tell("\"You don't have to thank me!\"\n");
      return true;
    }
  } else if (isVerb(V.CALL) && (await VISIBLE$(PERELMAN))) {
    await PERFORM(V.TELL, PERELMAN);
    return true;
  } else if ((isVerb(V.SHOW, V.GIVE) && (g.PRSO == RECORD_BUFFER)) || (isVerb(V.TELL_ABOUT) && (g.PRSI == RECORD_BUFFER))) {
    if (loc(RYDER) == OFFICE) {
      await PERFORM(V.TELL, RYDER);
      return true;
    } else if (get(g.SIM_LEVEL_TABLE, 0) < 1) {
      tell("Perelman looks confused. \"But...you haven't entered ");
      printD(SIMULATION_MODE);
      tell(" yet!\"\n");
      return true;
    } else if (loc(GRIMWOLD) == g.HERE) {
      tell("Perelman looks a bit annoyed. \"PRISM, talk to me later. This test is very important!\"\n");
      return true;
    }
    if (await VISIBLE$(PERELMAN)) {
      await CLEAR_BUF();
    }
    g.REVIEWING_RECORDINGS = true;
    await QUEUE(I_VIEW.id, getProp(RECORD_BUFFER, P.SIZE) + 5);
    disable(await INT(I_PERELMAN.id));
    move(PERELMAN, LOCAL_GLOBALS);
    move(COFFEE, LOCAL_GLOBALS);
    tell("Perelman looks intrigued. \"You've recorded something interesting, eh? Let me get a few of my colleagues together, and we'll view the buffer. I'll let you know when we're done, okay?\" He leaves the room.\n");
    return true;
  } else if (isVerb(V.EXAMINE)) {
    tell("Perelman is an older man, in his late fifties, and has a white goatee.\n");
    return true;
  } else {
    return false;
  }
}

