async function WEATHER_SHARE() {
  let cnt = 0, date_offset = 1;
  if (g.DATE == 17) {
    date_offset = 2;
  } else if (g.DATE == 19) {
    date_offset = 3;
  }
  tell("\"Here are tomorrow's high temperatures, in Celsius, for the major metros: ");
  loop1: for (;;) {
    tell(S(get(g.WEATHER_TABLE, cnt)), N(get(g.WEATHER_TABLE, cnt + date_offset)));
    cnt = cnt + 4;
    if (cnt > 32) {
      break loop1;
    }
  }
  tell(". And that's today's forecast from Wally the Weatherman! Bob?\" The camera pans back to the anchorman. \"We're coming up on ");
  if (g.CLOCK_WAIT) {
    await TIME_PRINT(g.TIME);
  } else {
    await TIME_PRINT(g.TIME + 1);
  }
  if (g.TIME == 1439) {
    tell(", so stay tuned for all of the newest news of the new day");
  }
  tell(".\" A moment later, a deep gong sounds.\n");
  return true;
}

