async function INTERFACE_MODE_F() {
  if (isVerb(V.THROUGH, V.WALK_TO)) {
    if (g.MODE == INTERFACE_MODE) {
      (await ERR("You are already in ", true));
      printD(INTERFACE_MODE);
      tell(".\n");
      return M_FATAL;
    } else if (g.PART_FLAG == 4) {
      tell(S(g.NOT_ACTIVE), "\n");
      return M_FATAL;
    } else if (await PSYCH_CHECK()) {
      return M_FATAL;
    } else if (await SIMULATION_CHECK()) {
      return M_FATAL;
    }
    g.MODE = INTERFACE_MODE;
    await TURN_RECORD_OFF();
    await GOTO(INTERFACE_ROOM);
    move(CURRENT_FEED, INTERFACE_ROOM);
    tell(S(getProp(INTERFACE_MODE, P.LDESC)), "\nDo you want to see the ");
    printD(PORT_LIST);
    tell("?");
    if (await YES$()) {
      crlf();
      await PERFORM(V.READ, PORT_LIST);
      return true;
    } else {
      return true;
    }
  } else {
    return false;
  }
}

