async function SIM_STATUS(year, level) {
  let seconds = 0, tenths = 0;
  if (year == 2041) {
    seconds = g._2041_SECONDS;
    tenths = g._2041_TENTHS;
  } else if (year == 2051) {
    seconds = g._2051_SECONDS;
    tenths = g._2051_TENTHS;
  } else if (year == 2061) {
    seconds = g._2061_SECONDS;
    tenths = g._2061_TENTHS;
  } else if (year == 2071) {
    seconds = g._2071_SECONDS;
    tenths = g._2071_TENTHS;
  } else if (year == 2081) {
    seconds = g._2081_SECONDS;
    tenths = g._2081_TENTHS;
  }
  tell("Total of real-time simulation, Year ", N(year), ": ");
  await SPRINT(level);
  tell(".");
  if (seconds < 10) {
    tell("0");
  }
  tell(N(seconds), ".", N(tenths), "\n");
  return true;
}

