async function WNN_FEEDER_F() {
  if (WNN_FEEDER == g.WINNER) {
    if (isVerb(V.STATUS)) {
      tell("Transmitter: ");
      if (hasFlag(TRANSMITTER, ONBIT)) {
        tell("ON");
      } else {
        tell("OFF");
      }
      tell("\n\nCurrent Feed: ");
      if (!(hasFlag(TRANSMITTER, ONBIT))) {
        tell("NONE\n");
        return true;
      } else {
        printD(g.FEED_BUFFER);
        return crlf();
      }
    } else if (isVerb(V.ON) && (g.PRSO == TRANSMITTER)) {
      if (hasFlag(TRANSMITTER, ONBIT)) {
        tell("\"");
        return (await ERR("Transmitter is already on.\""));
      } else {
        setFlag(TRANSMITTER, ONBIT);
        if ((g.FEED_BUFFER == RECORD_BUFFER) && (g.RYDER_RECORDED > 1) && !(g.LOSE_COUNTER > 0)) {
          await QUEUE(I_WIN.id, 13);
        }
        tell("\"Transmitter is now on.\"\n");
        return true;
      }
    } else if (isVerb(V.OFF) && (g.PRSO == TRANSMITTER)) {
      if (hasFlag(TRANSMITTER, ONBIT)) {
        clearFlag(TRANSMITTER, ONBIT);
        g.INTERFACE_CHANGE = WNN_FEEDER;
        await QUEUE(I_INTERFACE_CHANGE.id, 22);
        if (await QUEUED$(I_WIN.id)) {
          disable(await INT(I_WIN.id));
        }
        tell("\"Transmitter is now off.\"\n");
        return true;
      } else {
        tell("\"");
        return (await ERR("Transmitter is already off.\""));
      }
    } else if (isVerb(V.SET) && (g.PRSO == CURRENT_FEED)) {
      await PERFORM(V.TRANSMIT, g.PRSI);
      return true;
    } else if (isVerb(V.TRANSMIT)) {
      if (!(hasFlag(TRANSMITTER, ONBIT))) {
        tell("\"");
        return (await ERR("Unable to fulfill request. Transmitter not currently active.\""));
      } else if (g.PRSO == g.FEED_BUFFER) {
        tell("\"");
        (await ERR("Already transmitting ", true));
        await DPRINT(g.PRSO);
        tell(".\"\n");
        return true;
      } else if (hasFlag(g.PRSO, BUFFERBIT)) {
        g.FEED_BUFFER = g.PRSO;
        if ((await QUEUED$(I_WIN.id)) && !(g.PRSO == RECORD_BUFFER)) {
          disable(await INT(I_WIN.id));
        }
        g.INTERFACE_CHANGE = WNN_FEEDER;
        await QUEUE(I_INTERFACE_CHANGE.id, 22);
        if ((g.PRSO == RECORD_BUFFER) && (g.RYDER_RECORDED > 1) && !(g.LOSE_COUNTER > 0)) {
          await QUEUE(I_WIN.id, 13);
        }
        tell("\"Now transmitting ");
        await DPRINT(g.PRSO);
        tell(".\"\n");
        return true;
      } else {
        tell("\"");
        return (await ERR("Only buffer contents can be transmitted by this unit.\""));
      }
    } else if (isVerb(V.HELLO)) {
      tell(S(g.CONTACT), "\n");
      return true;
    } else {
      tell(S(g.BEYOND_BOUNDS), "\n");
      return await CLEAR_BUF();
    }
  } else {
    return false;
  }
}

