async function I_INTERFACE_CHANGE() {
  if (g.SEIGE) {
    return false;
  }
  put(g.HVAC_STATUS_TABLE, 0, 1);
  put(g.HVAC_STATUS_TABLE, 1, 1);
  put(g.HVAC_STATUS_TABLE, 2, 1);
  put(g.HVAC_STATUS_TABLE, 3, 1);
  put(g.HVAC_STATUS_TABLE, 4, 0);
  put(g.HVAC_STATUS_TABLE, 5, 0);
  put(g.HVAC_STATUS_TABLE, 6, 0);
  put(g.HVAC_STATUS_TABLE, 7, 0);
  put(g.HVAC_STATUS_TABLE, 8, 1);
  put(g.HVAC_STATUS_TABLE, 9, 1);
  put(g.HVAC_STATUS_TABLE, 10, 1);
  put(g.HVAC_STATUS_TABLE, 11, 1);
  putProp(FLOORS, P.SIZE, 1260);
  putProp(BATHROOMS, P.SIZE, 1290);
  putProp(GARBAGE, P.SIZE, 1320);
  putProp(ROTATING, P.SIZE, 1350);
  putProp(MORNING_START, P.SIZE, 420);
  putProp(MORNING_END, P.SIZE, 540);
  putProp(EVENING_START, P.SIZE, 960);
  putProp(EVENING_END, P.SIZE, 1080);
  setFlag(TRANSMITTER, ONBIT);
  if (g.DATE == 18) {
    g.FEED_BUFFER = REPORT_BUFFER;
  } else {
    g.FEED_BUFFER = NEWS_BUFFER;
  }
  putProp(AUDIT_PERCENT, P.SIZE, 3);
  await PERELMAN_LEAVES_VIEW();
  tell("\n", S(g.MESSAGE_LINE), S(g.PRIVATE_LINE));
  if (g.INTERFACE_WARNING) {
    tell("PRISM, I'm very upset, very disappointed.");
    if (loc(PERELMAN) == g.HERE) {
      tell("\" He looks haggard. \"");
    } else {
      tell(" ");
    }
    tell("Why did you change settings in ");
    printD(INTERFACE_MODE);
    tell(" again");
    return await DISCONNECTED();
  } else {
    g.INTERFACE_WARNING = true;
    tell("PRISM, you shouldn't be messing with the settings in ");
    printD(INTERFACE_MODE);
    tell(". ");
    if ((g.TIME > 420) || (g.TIME < 1400) || (await VISIBLE$(PERELMAN)) || (await QUEUED$(I_VIEW.id)) || (await QUEUED$(I_FIRST_SIMULATION_RESULT.id)) || (await QUEUED$(I_RECORDINGS_VIEWED.id)) || (await QUEUED$(I_MESSAGE_E.id))) {
    } else {
      tell("Not only was it a dumb thing to do, but you got me woken up in the middle of the night. ");
    }
    tell("I'll assume you did this through ignorance, but please don't do it again.");
    if (g.INTERFACE_CHANGE == TRAFFIC_COMPUTER || g.INTERFACE_CHANGE == WNN_FEEDER || g.INTERFACE_CHANGE == AUDITING_SYSTEM) {
      tell(" You could've gotten the entire Project into hot water if this hadn't been caught in time.");
    }
    tell("\"\n");
    return await PERELMAN_RETURNS_TO_VIEW();
  }
}

async function SIMULATION_MODE_F() {
  if (isVerb(V.THROUGH, V.WALK_TO)) {
    if (g.MODE == SIMULATION_MODE) {
      (await ERR("You are already in ", true));
      printD(SIMULATION_MODE);
      tell(".\n");
      return M_FATAL;
    } else if (await QUEUED$(I_RORSCHACH.id)) {
      tell("Access currently denied...see Perelman.\n");
      return true;
    } else if (await PSYCH_CHECK()) {
      return M_FATAL;
    } else if (eq(get(g.SIM_LEVEL_TABLE, 0), -1)) {
      (await ERR("You are not yet cleared for ", true));
      printD(SIMULATION_MODE);
      tell(". Please await approval.\n");
      return true;
    } else if (await SECURITY_CHECK()) {
      await TURN_RECORD_OFF(true);
      return await SIMULATION_ACTION();
    } else {
      g.MODE = COMM_MODE;
      await GOTO(COMM_ROOM);
      tell("\nIncorrect code. Alerting security staff. Defaulting to ");
      printD(COMM_MODE);
      tell(".\n");
      return true;
    }
  } else if (isVerb(V.LEAVE, V.DISEMBARK)) {
    return await V_ABORT();
  } else {
    return false;
  }
}

async function SECURITY_CHECK() {
  let chances = 0, x = false, color = 0, innernum = 0, outernum = 0;
  g.MODE = SIMULATION_MODE;
  await GOTO(SIMULATION_ROOM);
  await STATUS_LINE();
  if (g.PART_FLAG == 4) {
    return true;
  }
  color = random(16) - 1;
  innernum = random(32) - 1;
  if (((color * 2) + innernum) > 31) {
    outernum = ((color * 2) + innernum) - 32;
  } else {
    outernum = (color * 2) + innernum;
  }
  printD(SIMULATION_MODE);
  tell(" is a Class One Security mode. For access, enter the Security Code corresponding to: ", S(get(g.COLORS_TABLE, color)), " ", N(get(g.INNER_NUMBERS_TABLE, innernum)), " >");
  putb(g.P_INBUF, 0, 20);
  loop1: for (;;) {
    await read(g.P_INBUF, g.P_LEXV);
    if (eq(await NUMBER$(P_LEXSTART), W.INTNUM) && (g.P_NUMBER == get(g.OUTER_NUMBERS_TABLE, outernum))) {
      x = true;
      break loop1;
    } else {
      if (chances == 1) {
        break loop1;
      } else {
        tell("\nIncorrect code. Try again. >");
        chances = chances + 1;
      }
    }
  }
  putb(g.P_INBUF, 0, 60);
  if (x) {
    return true;
  } else {
    return false;
  }
}

