async function I_RYDER() {
  await QUEUE(I_RYDER.id, -1);
  g.RYDER_COUNTER = g.RYDER_COUNTER + 1;
  if (g.RYDER_COUNTER == 1) {
    move(RYDER, OFFICE);
    move(PERELMAN, OFFICE);
    setFlag(PERELMAN, NDESCBIT);
    if (g.HERE == OFFICE) {
      tell("\nThe office door opens, and Doctor Perelman walks in. You can see at least two National Guardsmen stationed outside the door. A moment later, a second man walks in, a man with a charismatic presence, a man you instantly recognize from myriad news reports -- Richard Ryder.\n");
      return true;
    } else {
      return false;
    }
  } else if ((g.RYDER_COUNTER == 2) && (g.HERE == OFFICE)) {
    tell("\n\"How dare you come in here with all...\" Perelman begins yelling, before Ryder cuts him off with a sharp \"Shut up, Perelman! I'm doing the talking here, so get used to it! You're not in control here anymore, and I am!\"");
    return await PERELMAN_NOTICES();
  } else if ((g.RYDER_COUNTER == 3) && (g.HERE == OFFICE)) {
    tell("\n\"Now let's get a few ground rules straight, Perelman. Nothing is stopping the Plan. Even if I ");
    (await ITALICIZE("didn't", true));
    tell(" think your damn tapes were faked, I wouldn't give a damn. A helluva lot of people have a helluva lot at stake in this thing, and so what if a lot of creeps who can't take care of themselves get a little hurt.\" \"I'm very frightened, Senator,\" says Perelman, his voice laced with sarcasm. \"Shut up,\" Ryder shouts back. \"I said that I'm doing the talking here!\"");
    return await PERELMAN_NOTICES();
  } else if ((g.RYDER_COUNTER == 4) && (g.HERE == OFFICE)) {
    tell("\n\"And let me tell you another thing, Perelman. Don't think that just because you've been on the news and been a big hot shot around here, you're gonna get some special consideration, because all that doesn't mean diddly-squat in the kind of power circles I'm talking about!\"");
    return await PERELMAN_NOTICES();
  } else if ((g.RYDER_COUNTER == 5) && (g.HERE == OFFICE)) {
    tell("\nRyder is getting really worked up; his normal, fatherly demeanor is completely gone. \"Perelman, you're an even bigger idiot than I imagined if you think we'd let some two-bit egghead scientist and some high-tech whiz bang computer stand in our way! Remember this -- if you were to have some unforeseen accident, you wouldn't be the first person who's gotten crushed by standing in the way of the Plan!\"");
    if (g.PERELMAN_NOTICED) {
      tell(" Perelman, with a quick glance in your direction, says, \"Quite an oration, Senator. Vintage thug. I wish I could save it for posterity. Would you be willing to go on the record with that statement?\" Ryder becomes even more livid. \"A real jokester, huh? Lemme tell you this, Perelman -- you'd better stop joking and start listening to my advice, or you're not going to be around to care about posterity, understand?\"");
    }
    return await PERELMAN_NOTICES();
  } else if (g.RYDER_COUNTER == 6) {
    move(PERELMAN, LOCAL_GLOBALS);
    move(COFFEE, LOCAL_GLOBALS);
    if ((await VISIBLE$(PERELMAN)) && (PERELMAN == g.WINNER)) {
      await CLEAR_BUF();
    }
    move(RYDER, LOCAL_GLOBALS);
    clearFlag(PERELMAN, NDESCBIT);
    disable(await INT(I_RYDER.id));
    if (g.HERE == OFFICE) {
      if (g.RECORDING) {
        g.RYDER_RECORDED = g.RYDER_RECORDED + 1;
      }
      tell("\n\"So, here's the bottom line, Perelman. My men are going to stay here and keep the lid shut tight on you troublemakers, until the Plan is the law of this land. Nobody leaves, no communications at all, and don't worry about visitors; we'll take care of that. And if I get any trouble out of you, I swear to God I'll personally pull the plug on that goddam wonder machine of yours. Got it?\" He stomps out without waiting for a reply, leaving Perelman sputtering in anger. A few seconds later, National Guardsmen enter and escort Perelman away.\n");
      return true;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function PERELMAN_NOTICES() {
  if (g.RECORDING) {
    g.RYDER_RECORDED = g.RYDER_RECORDED + 1;
  }
  if (g.PERELMAN_NOTICED) {
    return crlf();
  } else {
    g.PERELMAN_NOTICED = true;
    tell(" Perelman suddenly stiffens ever so slightly and nonchalantly slides some papers across his desk, as though to cover something.\n");
    return true;
  }
}

async function I_WIN() {
  tell("\n", S(g.MESSAGE_LINE), "\"PRISM!\" It's Perelman, sounding giddy with joy. \"You've done it! That was brilliant, absolutely brilliant, sending your recordings out over the World News Network! Ryder just left here so fast and so mad like nothing I've ever seen! The switchboard is lighting up like crazy, and I just got off the phone with President Bowden himself!\" You hear the sound of whooping and cheering in the background, and Perelman gives a \"Yeehah!\" more suited to a Texas cattle rancher than a Jewish big-city scientist. \"The National Guard unit has just been recalled! PRISM, the Plan is dead in the water -- you're a hero!\"");
  await CONTINUE();
  disable(await INT(I_LOSE.id));
  g.MODE = COMM_MODE;
  g.MONTH = g.MONTH + 1;
  g.DATE = g.DATE - 2;
  g.TIME = 600 + random(360);
  g.HERE = NEWS;
  move(PLAYER, NEWS);
  await CHAPTER_PRINT(4);
  tell("\n\n\n\n");
  await PRINT_SPACES(22);
  tell("\"A mind forever voyaging through\n");
  await PRINT_SPACES(23);
  tell("strange seas of thought, alone.\"\n");
  await PRINT_SPACES(40);
  tell("-- William Wordsworth\n\n\n\n\n");
  await CONTINUE();
  await INIT_STATUS_LINE(2);
  return await V_LOOK();
}

async function I_LOSE() {
  if (await QUEUED$(I_WIN.id)) {
    await QUEUE(I_LOSE.id, 10);
    return false;
  }
  await QUEUE(I_LOSE.id, -1);
  g.LOSE_COUNTER = g.LOSE_COUNTER + 1;
  if (g.HERE == CORE) {
    tell("\nYou suddenly notice something at the very edge of your viewing range: Perelman is being worked over by a couple of muscular thugs, both carrying illegalized fireguns. Perelman looks dazed and disheveled. A moment later ");
    printD(RYDER);
    tell(" strides into your field of vision. \"He won't crack, boss,\" shrugs one of the toughies. \"Okay, waste him,\" growls Ryder. As you watch in helpless horror, gouts of flame from the guns envelop your creator. You attempt to turn away, or close your eyes, but of course you're not equipped to do so.\n\n\"Okay, now melt this pile of junk over here,\" barks the Senator, pointing at some of your own machinery. Fire pours from the guns again, and suddenly the universe goes away.\n");
    return await FINISH();
  } else if (g.LOSE_COUNTER == 1) {
    tell("\n", S(g.MESSAGE_LINE), "\"PRISM!\" It's Perelman's voice. \"Help! Main--\" The message line suddenly goes dead.\n");
    return true;
  } else if (g.LOSE_COUNTER == 6) {
    tell("\nYou feel something akin to a stabbing pain. Your consciousness slips quickly away...\n");
    return await FINISH();
  } else {
    return false;
  }
}

async function END_IT() {
  tell("\nWith the gentlest bump, the skycab settles into a landing bay at the spaceport terminal. Jill reaches over and gives your hand an excited squeeze. Through the window of the skycab, you can see the sleek, white shuttle waiting to carry you on your first leg of the journey to...to what? The Silver Dove would be more than just another space colony. It was the pinnacle of an eon of human achievement, the first step into interstellar space.\n\nYou and Jill would never live to see the completion of that first step, generations hence. (Although in the germfree, low-gee environment of a habitat, and with the recent strides in health and longevity research, who could say for sure?) But you would still have been part of that dawning of a new age, that future of unlimited potential. Humanity was beginning a journey into the universe, a voyage that would last forever.");
  await CONTINUE();
  clearScreen(-1);
  await PRINT_SPACES(30);
  tell("ACKNOWLEDGEMENTS\n\n");
  await TITLE_PRINT();
  tell(" would not have been possible without the effort of many people. Marc Blank made the changes to our development tools that \"pushed back the envelope\" and made Interactive Fiction Plus (tm) a reality.\n\nAs always, all the other authors pitched in when needed, but I want to particularly acknowledge the help of Stu Galley and Jerry Wolper.\n\nAs a former playtester, I can say with authority that the testing of ");
  await TITLE_PRINT();
  tell(" was superb. I appreciate the efforts of everyone who tested, especially Amy Briggs, Gary Brennan, Tomas Bok, Max Buxton, and Suzanne Frank.\n\nPaul Gross, Linde Simpson, Duncan Blanchard, Mike Morton, Rick Lay and Andy Kaluzniacki performed various wizardries on the micro-computers which run ");
  await TITLE_PRINT();
  tell(".\n\nThe package was designed by Carl Genatossio and Elizabeth Langosy. Package art was the work of Larry Winborg and Jess Nicholas, and photography the work of Ralph King.\n\nFinally, I'm extremely grateful to Jon Palace for immeasurable advice and support throughout this project.\n\n");
  await PRINT_SPACES(55);
  tell("-- SEM 9/85\n\n\n");
  return await quit();
}

